    public Object parseTransaction(Object transaction, Object... optionalArgs)
    {
        //
        // fetchDeposits
        //     {
        //         "coin": "PHP",
        //         "address": "Internal Transfer",
        //         "addressTag": "Internal Transfer",
        //         "amount": "0.02",
        //         "id": "31312321312312312312322",
        //         "network": "Internal",
        //         "transferType": "0",
        //         "status": 3,
        //         "confirmTimes": "",
        //         "unlockConfirm": "",
        //         "txId": "Internal Transfer",
        //         "insertTime": 1657623798000,
        //         "depositOrderId": "the deposit id which created by client"
        //     }
        //
        // fetchWithdrawals
        //     {
        //         "coin": "BTC",
        //         "address": "Internal Transfer",
        //         "amount": "0.1",
        //         "id": "1201515362324421632",
        //         "withdrawOrderId": null,
        //         "network": "Internal",
        //         "transferType": "0",
        //         "status": 0,
        //         "transactionFee": "0",
        //         "confirmNo": 0,
        //         "info": "{}",
        //         "txId": "Internal Transfer",
        //         "applyTime": 1657967792000
        //     }
        //
        // todo: this is in progress
        Object currency = Helpers.getArg(optionalArgs, 0, null);
        Object id = this.safeString(transaction, "id");
        Object address = this.safeString(transaction, "address");
        Object tag = this.safeString(transaction, "addressTag");
        if (Helpers.isTrue(!Helpers.isEqual(tag, null)))
        {
            if (Helpers.isTrue(Helpers.isLessThan(((String)tag).length(), 1)))
            {
                tag = null;
            }
        }
        Object txid = this.safeString(transaction, "txId");
        Object currencyId = this.safeString(transaction, "coin");
        Object code = this.safeCurrencyCode(currencyId, currency);
        Object timestamp = null;
        timestamp = this.safeInteger2(transaction, "insertTime", "applyTime");
        Object updated = null;
        Object type = null;
        Object withdrawOrderId = this.safeString(transaction, "withdrawOrderId");
        Object depositOrderId = this.safeString(transaction, "depositOrderId");
        if (Helpers.isTrue(!Helpers.isEqual(withdrawOrderId, null)))
        {
            type = "withdrawal";
        } else if (Helpers.isTrue(!Helpers.isEqual(depositOrderId, null)))
        {
            type = "deposit";
        }
        Object status = this.parseTransactionStatus(this.safeString(transaction, "status"));
        Object amount = this.safeNumber(transaction, "amount");
        Object feeCost = this.safeNumber(transaction, "transactionFee");
        Object fee = null;
        if (Helpers.isTrue(!Helpers.isEqual(feeCost, null)))
        {
            final Object finalFeeCost = feeCost;
            fee = new java.util.HashMap<String, Object>() {{
                put( "currency", code );
                put( "cost", finalFeeCost );
            }};
        }
        Object network = this.safeString(transaction, "network");
        Object intern = Helpers.isEqual(network, "Internal");
        final Object finalTimestamp = timestamp;
        final Object finalNetwork = network;
        final Object finalTag = tag;
        final Object finalType = type;
        final Object finalFee = fee;
        return new java.util.HashMap<String, Object>() {{
            put( "info", transaction );
            put( "id", id );
            put( "txid", txid );
            put( "timestamp", finalTimestamp );
            put( "datetime", Coinsph.this.iso8601(finalTimestamp) );
            put( "network", finalNetwork );
            put( "address", address );
            put( "addressTo", address );
            put( "addressFrom", null );
            put( "tag", finalTag );
            put( "tagTo", finalTag );
            put( "tagFrom", null );
            put( "type", finalType );
            put( "amount", amount );
            put( "currency", code );
            put( "status", status );
            put( "updated", updated );
            put( "internal", intern );
            put( "comment", null );
            put( "fee", finalFee );
        }};
    }

